from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-200, 200)
                       .Expiration(timedelta(0), timedelta(days=730))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.held_contract = None
        self.entry_fill_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.no_entry_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.AfterMarketOpen(self.spy, 0),
            self.OnExpirationProcessing
        )

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.OnTimeStop
        )

    def OnData(self, slice: Slice):
        if self.Portfolio[self.spy].Invested:
            quantity = self.Portfolio[self.spy].Quantity
            self.MarketOrder(self.spy, -quantity)
            self.Debug(f"Unexpected SPY exercise/assignment; liquidating {quantity} shares")

        if not self.HasOptionPosition() or self.held_contract is None:
            return

        if self.HasOpenOrder(self.exit_order_id):
            return

        quote = slice.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0 or self.entry_fill_price is None:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.CancelOpenExitOrder("Profit target reached")
            self.SubmitExit("Profit target")

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not previous_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_cross = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )
        if not bullish_cross:
            return

        end_time = bar.EndTime
        if end_time.hour < 9 or (end_time.hour == 9 and end_time.minute < 45):
            return
        if end_time.hour > 14 or (end_time.hour == 14 and end_time.minute > 30):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.HasOptionPosition() or self.HasOpenOrder(self.entry_order_id):
            return

        self.TryEnter(bar.Close)

    def TryEnter(self, spy_price):
        current_slice = self.CurrentSlice
        if current_slice is None or current_slice.OptionChains is None:
            self.Debug("Entry skipped: no current option chain")
            return

        chain = None
        for candidate in current_slice.OptionChains.Values:
            if candidate.Underlying is not None and candidate.Underlying.Symbol == self.spy:
                chain = candidate
                break

        if chain is None:
            self.Debug("Entry skipped: SPY option chain unavailable")
            return

        algorithm_date = self.Time.date()
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - algorithm_date).days >= 7
        ]

        if not calls:
            self.Debug("Entry skipped: no call expiration at least 7 calendar days out")
            return

        expiration = min(contract.Expiry.date() for contract in calls)
        eligible = [
            contract for contract in calls
            if contract.Expiry.date() == expiration
            and contract.Strike >= spy_price * 1.01
        ]

        if not eligible:
            self.Debug("Entry skipped: no eligible 1% OTM call at selected expiration")
            return

        selected = min(eligible, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} expiry {expiration} strike {selected.Strike}"
        )

    def OnTimeStop(self):
        if not self.HasOptionPosition() or self.held_contract is None:
            return

        next_trading_day = self.NextSpyTradingDay(self.Time.date())
        if self.held_contract.ID.Date.date() == next_trading_day:
            self.CancelOpenExitOrder("Time stop")
            self.SubmitExit("Pre-expiration time stop")

    def OnExpirationProcessing(self):
        if self.held_contract is None:
            return

        if self.held_contract.ID.Date.date() > self.Time.date():
            return

        self.no_entry_date = self.Time.date()

        if self.HasOpenOrder(self.entry_order_id):
            self.Transactions.GetOrderTicket(self.entry_order_id).Cancel(
                "Expiration processing"
            )

        if self.HasOptionPosition():
            self.CancelOpenExitOrder("Expiration processing")
            self.SubmitExit("Expiration processing")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {order_event.FillPrice}"
                )

            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}"
                )
                if not self.HasOptionPosition():
                    self.held_contract = None
                    self.entry_fill_price = None

            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

    def SubmitExit(self, reason):
        if not self.HasOptionPosition() or self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0 or self.HasOpenOrder(self.exit_order_id):
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {reason} for {self.held_contract}")

    def CancelOpenExitOrder(self, reason):
        if self.HasOpenOrder(self.exit_order_id):
            self.Transactions.GetOrderTicket(self.exit_order_id).Cancel(reason)

    def HasOptionPosition(self):
        return (
            self.held_contract is not None and
            self.Portfolio[self.held_contract].Invested
        )

    def HasOpenOrder(self, order_id):
        if order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(order_id)
        if ticket is None:
            return False

        return ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

    def NextSpyTradingDay(self, date):
        candidate = date + timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(candidate, False):
            candidate += timedelta(days=1)

        return candidate

