        self.closes = RollingWindow[float](21)
        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.held_symbol = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_exit_order_id = None
        self.entry_price = None
        self.no_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        self.closes.Add(bar.Close)

        if self.closes.Count < 21:
            return

        current_fast = sum(self.closes[i] for i in range(5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(20)) / 20.0
        prior_fast = sum(self.closes[i] for i in range(1, 6)) / 5.0
        prior_slow = sum(self.closes[i] for i in range(1, 21)) / 20.0

        bar_end = bar.EndTime
        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if not (prior_fast <= prior_slow and current_fast > current_slow):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.entry_order_id is not None or self.exit_order_id is not None:
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        self.TryEnterCall(bar.Close)

    def TryEnterCall(self, spy_price):
        chain = None
        try:
            if self.option_symbol in self.CurrentSlice.OptionChains:
                chain = self.CurrentSlice.OptionChains[self.option_symbol]
        except Exception:
            chain = None

        if chain is None:
            self.Debug("Entry skipped: no SPY option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not calls:
            self.Debug("Entry skipped: no eligible call expiration.")
            return

        expiry = min(contract.Expiry.date() for contract in calls)
        minimum_strike = spy_price * 1.01
        candidates = [
            contract for contract in calls
            if contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no eligible OTM call.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        self.held_symbol = selected.Symbol
        ticket = self.MarketOrder(self.held_symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.entry_price = None
        self.Debug("Entry submitted: {0}".format(self.held_symbol))

