            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no eligible OTM call.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        self.held_symbol = selected.Symbol
        ticket = self.MarketOrder(self.held_symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.entry_price = None
        self.Debug("Entry submitted: {0}".format(self.held_symbol))

    def OnData(self, data):
        if self.Portfolio[self.spy].Invested and self.equity_exit_order_id is None:
            quantity = self.Portfolio[self.spy].Quantity
            if quantity != 0:
                ticket = self.MarketOrder(self.spy, -quantity)
                self.equity_exit_order_id = ticket.OrderId
                self.Debug("Unexpected SPY exercise/assignment; liquidation submitted.")

        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            if self.entry_order_id is None and self.exit_order_id is None:
                self.held_symbol = None
                self.entry_price = None
            return

        expiry_date = self.held_symbol.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.no_entry_date = self.Time.date()
            self.SubmitExit("expiration processing")
            return

        if (self.Time.date() == expiry_date - timedelta(days=1)
                and self.Time.time() == time(15, 45)):
            self.SubmitExit("pre-expiration time stop")
            return

        if self.entry_price is None or self.exit_order_id is not None:
            return

        quote = None
        try:
            if self.held_symbol in data.QuoteBars:
                quote = data.QuoteBars[self.held_symbol]
        except Exception:
            quote = None

        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("profit target")

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.Transactions.CancelOrder(order.Id)

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug("Exit submitted ({0}): {1}".format(reason, self.held_symbol))

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    "Entry filled: {0} @ {1:.2f}".format(
                        self.held_symbol, self.entry_price
                    )
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug("Entry canceled or invalid.")
                self.entry_order_id = None
                if self.held_symbol is not None and not self.Portfolio[self.held_symbol].Invested:
                    self.held_symbol = None
                    self.entry_price = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {0}".format(self.held_symbol))
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if order_event.OrderId == self.equity_exit_order_id:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.equity_exit_order_id = None
